from fastapi import FastAPI
from pydantic import BaseModel
app=FastAPI()
class Item(BaseModel):
    name:str
    price:float
items={}
@app.post('/items')
def create(item:Item):
    import uuid
    tid=str(uuid.uuid4())
    items[tid]=item
    return {'id':tid,'item':item}
@app.get('/items/{tid}')
def get(tid:str):
    return items[tid]
